-- Update only untouched defaults; preserve administrator-authored content.
UPDATE cms_block SET body='Ստեղծեք պլան, հաստատեք բաժինները, խմբագրեք և ներբեռնեք DOCX։ AI գեներացիան պահանջում է միացված ծառայություն և Coins։',version=version+1 WHERE block_key='tools' AND body='Այս պահին հասանելի է ձեռքով խմբագրումը։ AI գործիքները մշակման փուլում են։';
UPDATE cms_block SET body='AI գեներացիայից առաջ Coins-ը ամրագրվում է։ Վերջնական արժեքը չի գերազանցում հաստատված գնահատականը։ Իրական վճարումները դեռ միացված չեն։',version=version+1 WHERE block_key='pricing' AND body='Հետագայում Coins-ը կօգտագործվի AI գործիքների համար։ Այժմ սևագրերի ստեղծումն ու խմբագրումն անվճար են։ Գնումները դեռ հասանելի չեն։';
UPDATE cms_block SET items_json='[{"title":"Ի՞նչ կարող եմ անել հիմա։","body":"Ստեղծել, խմբագրել և ներբեռնել փաստաթղթեր DOCX ձևաչափով։"},{"title":"AI գեներացիան հասանելի՞ է։","body":"Այո՝ ծառայության կարգավորումից հետո։ Թեստային ռեժիմը հստակ նշվում է և չի ստեղծում իրական AI բովանդակություն։"},{"title":"Կա՞ ամսական բաժանորդագրություն։","body":"Ոչ։ Գեներացիան օգտագործում է Coins։ Իրական վճարումները դեռ միացված չեն։"}]',version=version+1 WHERE block_key='faq' AND version=0;
UPDATE cmscontent SET content_value='Հարթակը մշակման փուլում է։ AI գեներացիան պահանջում է ծառայության կարգավորում։ Իրական վճարումները դեռ միացված չեն։ Գործարկումից առաջ այստեղ պետք է հրապարակվեն ծառայության ամբողջական պայմանները։' WHERE content_key='terms' AND content_value='Հարթակը մշակման փուլում է։ AI և վճարային ծառայությունները դեռ հասանելի չեն։ Գործարկումից առաջ այստեղ պետք է հրապարակվեն ծառայության ամբողջական պայմանները։';
